const text = String($json.output || '').trim();
const match = text.match(/^SUBJECT:\s*(.+)$/m);
const subject = match ? match[1].trim() : 'Morning roundup';
const body = match ? text.replace(match[0], '').trim() : text;
const date = $now.toFormat('d LLL');
return { json: { subject: `[${date}] ${subject}`, body } };
